"Its words as the lyrics have them: change what you will, and it is sung anew from its start to its end; the rest of the take stays as it is.": "Яе словы, як яны стаяць у лірыцы: змяні што хочаш, і яе праспяваюць нанова ад пачатку да канца; астатняе ў дублі застанецца як ёсць.",
