"0: to the end": "0: да канца",
"De-ess": "Дэ-эсер",
"De-ess strength": "Сіла дэ-эсера",
"How strongly: subtle, or normal for a sharper voice.": "Наколькі моцна: мякка або звычайна — для больш рэзкага голасу.",
"Retune from 440 to 432 Hz (pitch and tempo together). Off keeps 440 Hz, for the public.": "Перабудаваць з 440 на 432 Гц (вышыня і тэмп разам). Выкл.: 440 Гц, для публікі.",
"Brings the song to the loudness below: measured first, then set in a second pass. Off: the level stays as it came.": "Прыводзіць песню да гучнасці ніжэй: спачатку замер, потым устаноўка другім праходам. Выкл.: узровень застаецца як быў.",
"Loudness": "Гучнасць",
"The ceiling for the peaks between samples. −1 leaves room for the MP3 and AAC encoders, which add peaks of their own.": "Столь для пікаў паміж адлікамі. −1 пакідае месца кодэрам MP3 і AAC, якія дадаюць свае пікі.",
"Also an MP3 at 320 kbps, beside the WAV and the FLAC.": "Яшчэ і MP3 на 320 kbps, побач з WAV і FLAC.",
"also MP3": "і MP3",
"What is upscaled: the take, or any file made from it but an upscaled one.": "Што апскейліцца: сэмпл або любы файл, створаны з яго, акрамя ўжо апскейленага.",
"Mode": "Рэжым",
"how deep it redraws": "наколькі глыбока перамалёўвае",
