"Extreme — above 4 kHz": "Гранічна — вышэй за 4 кГц",
"How many versions to draw: they differ only by the noise, and each takes as long as the first. Two let you pick by ear.": "Колькі версій маляваць: яны адрозніваюцца толькі шумам, і кожная ідзе столькі ж, колькі першая. Дзве даюць абраць на слых.",
"Variants": "Варыянты",
"Keep the original below the cutoff": "Пакінуць арыгінал ніжэй зрэзу",
"What is debuzzed: the take, or a file made from it that is neither debuzzed nor upscaled.": "Што ідзе ў антыгул: сэмпл або файл з яго, які яшчэ не прайшоў антыгул і апскейл.",
"Strength": "Сіла",
"How much of the frame ripple to divide out. Viktor's ear: 100 % thinned the opening, 80 % was right.": "Якую долю кадравай пульсацыі прыбраць. Вуха Віктара: 100 % патанчылі пачатак, 80 % — якраз тое.",
"Which file is measured: the take, or any file made from it.": "Які файл мераць: сэмпл або любы файл з яго.",
"Inspect": "Праверыць",
"Where the sound sits: spectrogram, average spectrum, band energy. Lay another take over it to compare.": "Дзе сядзіць гук: спектраграма, сярэдні спектр, энергія палос. Накладзі іншы сэмпл для параўнання.",
"Log": "Лог",
"Linear": "Лінейная",
"Lays a second spectrum under this one, on the same scale: a file made from this take, or another take.": "Кладзе другі спектр пад гэты, у тым жа маштабе: файл з гэтага сэмпла або іншы сэмпл.",
"Compare with": "Параўнаць з",
"Full screen: zoom and scroll (or double-click the picture). A click plays from there when this take is in the player.": "На ўвесь экран: маштаб і пракрутка (або падвойны пстрык па малюнку). Пстрык грае з таго месца, калі гэты сэмпл у плэеры.",
"Full screen: zoom and scroll": "На ўвесь экран: маштаб і пракрутка",
