"FLAC: lossless, about half the size of WAV. WAV: for tools that take nothing else.": "FLAC: без страт, прыкладна ўдвая меншы за WAV. WAV: для праграм, якія іншага не бяруць.",
"Also every file made from each take (remasters, stems, upscales, debuzzed files), named after the take.": "А таксама кожны файл, створаны з кожнага сэмпла (рэмастэры, стэмы, апскейлы, файлы пасля антыгулу), з імем па сэмпле.",
"with what is made from them": "з усім, што з іх створана",
"A ZIP made on Forge, then saved by the browser where you tell it": "ZIP збіраецца на Forge, потым браўзер захоўвае яго, куды скажаш",
"Export ZIP": "Экспарт ZIP",
"To the trash": "У кошык",
"The Librarian lives in Forge's lab, which does not answer: not found": "Бібліятэкар жыве ў лабараторыі Forge, а яна не адказвае: не знойдзена",
"a LoRA for YuE2 from your own songs · the guide: LORA-TRAINING.md": "LoRA для YuE2 з тваіх песень · даведнік: LORA-TRAINING.md",
"Reload": "Абнавіць",
"Train steps": "Крокі трэніроўкі",
