"Train": "Трэніроўка",
"Telemetry": "Тэлеметрыя",
"a run: its curves and epochs": "ран: яго крывыя і эпохі",
"a folder of songs in": "тэчка з песнямі ў",
"; pick it, choose the tracks, give each its lyrics": "; абяры яе, адбяры трэкі, дай кожнаму яго тэкст",
"Ready sets to try a first adapter with: GTSinger joined into songs, Russian and English": "Гатовыя наборы для першага адаптара: GTSinger, сшыты ў песні, руская і англійская",
"Starter sets": "Стартавыя наборы",
"All in": "Усе ў набор",
