"a caption for every track: the style line, then the lyrics; made into": "подпіс для кожнага трэка: радок стылю, потым тэкст; запісваецца ў",
"Trigger word": "Слова-трыгер",
"calls the style by name later": "потым выклікае стыль па імені",
