"Steps": "Крокі",
"An adapter is saved every this many epochs (an epoch: every song once), each to be heard and compared.": "Адаптар захоўваецца кожныя столькі эпох (эпоха: кожная песня па разе), каб кожны пачуць і параўнаць.",
"Save every": "Захоўваць кожныя",
"epochs": "эпох",
"Rank": "Ранг",
"Which rank, how many steps, the other knobs: the guide": "Які ранг, колькі крокаў, іншыя ручкі: даведнік",
"How to choose ›": "Як абраць ›",
"How big each step is. Keep the kind's own; higher learns faster and forgets more.": "Наколькі вялікі кожны крок. Пакінь значэнне віду; вышэй — вучыцца хутчэй і больш забывае.",
"Learning rate": "Хуткасць навучання",
"AR weight": "Вага AR",
"0 = sound only": "0 = толькі гук",
"Holds the music half near the base model, so it keeps what it was not shown; higher holds tighter.": "Трымае музычную палову каля базавай мадэлі, каб яна захавала тое, чаго ёй не паказвалі; вышэй — трымае мацней.",
"AR anchor (KL)": "Якар AR (KL)",
"AR speed": "Хуткасць AR",
