"Each song renders {#0} times with sound seeds seed, seed + 1…; the music is written once.": {"one": "Кожная песня гучыць {0} раз з гукавымі сідамі seed, seed + 1…; музыка пішацца адзін раз.", "few": "Кожная песня гучыць {0} разы з гукавымі сідамі seed, seed + 1…; музыка пішацца адзін раз.", "many": "Кожная песня гучыць {0} разоў з гукавымі сідамі seed, seed + 1…; музыка пішацца адзін раз.", "other": "Кожная песня гучыць {0} раза з гукавымі сідамі seed, seed + 1…; музыка пішацца адзін раз."},
