"Regenerate from a moment": "Перагенераваць з моманту",
"Keep {0} up to which moment (m:ss)? The music is written anew from there.": "Да якога моманту пакінуць {0} (х:сс)? Далей музыка пішацца нанава.",
"A moment between 0:01 and {0}": "Момант паміж 0:01 і {0}",
"This take's request carries no music codes to keep": "У запыце гэтага сэмпла няма музычных кодаў, якія можна пакінуць",
"Writing {0} anew from {1}; everything before stays": "{0} пішацца нанава з {1}; усё, што раней, застаецца",
"Listening… {#0} s": "Слухае… {0} с",
"No line of the text was heard in this take": "У гэтым сэмпле не пачута ніводнага радка тэксту",
"Where the text ends cannot be told with confidence here ({0} of {1} lines heard in order, the last at line {2}): nothing trimmed. Whisper hears some languages badly.": "Дзе заканчваецца тэкст, тут упэўнена не сказаць (па парадку пачута {0} з {1} радкоў, апошні — радок {2}): нічога не абрэзана. Некаторыя мовы Whisper чуе дрэнна.",
"The text runs to the end ({0} of {1}): nothing to trim": "Тэкст ідзе да канца ({0} з {1}): абразаць няма чаго",
"The text ends at {0} of {1} ({2} of {3} lines heard in order).": "Тэкст заканчваецца на {0} з {1} (па парадку пачута {2} з {3} радкоў).",
"Render this take again, cut at {0}? The same performance; only the sound stage runs.": "Агучыць гэты сэмпл нанава з абрэзкай на {0}? Тое ж выкананне; працуе толькі гукавая стадыя.",
