"{0}. Click to check again.": "{0}. Пстрык — праверыць зноў.",
"The browser could not reach {0}. Either the chat server is not running, or it refuses requests from this page (CORS): turn CORS on in its settings, or open this page from the same machine name.": "Браўзер не дастукаўся да {0}. Альбо чат-сервер не запушчаны, альбо ён адмаўляе запытам гэтай старонкі (CORS): уключы CORS у яго наладах або адкрый гэтую старонку з таго ж імя машыны.",
"Writer: the chat server at {0} does not answer. Start it there, or choose OpenRouter below. (Checked just now; entering the Writer checks again.)": "Пісьменнік: чат-сервер на {0} не адказвае. Запусці яго там або абяры OpenRouter ніжэй. (Праверана толькі што; уваход у Пісьменніка правярае зноў.)",
