"The whole take as a project of your DAW: the stems on their tracks, the score as MIDI, the tempo, the sections as regions, the lyrics on the timeline. Which DAW do you use?": "Увесь сэмпл як праект тваёй DAW: стэмы на сваіх дарожках, партытура як MIDI, тэмп, раздзелы як рэгіёны, тэкст на таймлайне. Якой DAW ты карыстаешся?",
"Asking the lab…": "Пытаемся ў лабараторыі…",
"The lab does not answer: {0}": "Лабараторыя не адказвае: {0}",
"✓ on the studio’s machine": "✓ на машыне студыі",
"✓ on the studio’s machine · {0}": "✓ на машыне студыі · {0}",
"not on the studio’s machine; on your own computer it may well be": "не на машыне студыі; на тваім камп'ютары цалкам можа быць",
"How to install it": "Як усталяваць",
"Your DAW ✓": "Твая DAW ✓",
"I use this one": "Я карыстаюся гэтай",
"Export the take": "Экспартаваць сэмпл",
"A DAWproject: the mix, the stems, the score as notes, the sections as markers": "DAWproject: мікс, стэмы, партытура нотамі, раздзелы маркерамі",
"first": "першая",
"next": "наступная",
"Now: the": "Зараз:",
"project (the mix, every stem, the score as MIDI; the lyrics and sections once the take is timed in the Refiner’s lyrics check), and": "— праект (мікс, кожны стэм, партытура як MIDI; тэкст і раздзелы — калі сэмпл размечаны па часе ў праверцы тэксту ў Гранільшчыка), і",
"(the mix, every stem, the score as notes, the sections as markers: Waveform 14, Bitwig, Studio One, Cubase); both also in a take’s menu → Download. Waveform: 14 or newer.": "(мікс, кожны стэм, партытура нотамі, раздзелы маркерамі: Waveform 14, Bitwig, Studio One, Cubase); абодва ёсць і ў меню сэмпла → «Спампаваць». Waveform: 14 або навейшы.",
"Packing…": "Упакоўка…",
"60 days of evaluation with every function, then a licence: $60 for personal use or a small business": "60 дзён пробы з усімі функцыямі, потым ліцэнзія: $60 для асабістага карыстання або малога бізнесу",
"Waveform Free 14 or newer: free, no track or export limits; it opens the studio's DAWproject (File > Import Other > Import a DAWproject file). Waveform 13 is not supported": "Waveform Free 14 або навейшы: бясплатна, без абмежаванняў на дарожкі і экспарт; адкрывае DAWproject студыі (File > Import Other > Import a DAWproject file). Waveform 13 не падтрымліваецца",
"30 days without limits after signing up, then Essentials $99, Producer $199 or Studio $399 (bitwig.com, 03.10.2026); opens the studio's DAWproject: the mix, the stems, the score as notes, the sections as markers": "30 дзён без абмежаванняў пасля рэгістрацыі, потым Essentials $99, Producer $199 або Studio $399 (bitwig.com, 03.10.2026); адкрывае DAWproject студыі: мікс, стэмы, партытура нотамі, раздзелы маркерамі",
"reaper.fm/download.php → the Linux x86_64 tarball → unpack it and run ./install-reaper.sh (it goes to /opt/REAPER)": "reaper.fm/download.php → архіў Linux x86_64 → распакуй і запусці ./install-reaper.sh (ставіцца ў /opt/REAPER)",
"tracktion.com/products/waveform-free → the .deb of Waveform 14 for Linux → sudo apt install ./waveform14_*.deb": "tracktion.com/products/waveform-free → .deb Waveform 14 для Linux → sudo apt install ./waveform14_*.deb",
"bitwig.com/download: the Ubuntu .deb (sudo apt install ./bitwig-studio-*.deb) or the Flatpak": "bitwig.com/download: .deb для Ubuntu (sudo apt install ./bitwig-studio-*.deb) або Flatpak",
