"All the music strengths together. Measured on this studio's takes: the score came out whole up to {0} in every run, broken from 2.5 in every run. Green to {1}, amber to {2}, red past it.": "Усе музычныя сілы разам. Вымерана на сэмплах гэтай студыі: партытура выходзіла цэлай да {0} у кожным запуску і зламанай ад 2.5 у кожным. Зялёны да {1}, жоўты да {2}, далей чырвоны.",
