"⚠ {0}: {1} on the music half is past its limit {2}: the score tends to fail after 70-200 tokens.": "⚠ {0}: {1} на музычнай палове — вышэй за яе мяжу {2}: партытура звычайна ламаецца пасля 70–200 токенаў.",
"⚠ {0}: {1} on the sound half is past its limit {2}.": "⚠ {0}: {1} на гукавой палове — вышэй за яе мяжу {2}.",
"⚠ {0} plans instrumental scores: at {1} with words to sing, the score loses its vocal line (measured at 1.00: 1 note in 127 vocal bars, the music looping). Keep it low, 0.3–0.5, for a sung song.": "⚠ {0} плануе інструментальныя партытуры: на {1} са словамі для спеву партытура губляе вакальную лінію (замер на 1.00: 1 нота на 127 вакальных тактаў, музыка зацыкліваецца). Для песні са спевам трымай нізка, 0.3–0.5.",
"{#0} stacked: their changes add up.": "Накладзена: {0}; іх змены складаюцца.",
"⚠ The music half carries {0} together, past the shared ceiling {1}: runs this heavy wrote broken scores every time (measured). Lower some, or take one off the music half.": "⚠ Музычная палова нясе разам {0}, вышэй за агульную столь {1}: такія цяжкія запускі кожны раз пісалі зламаныя партытуры (вымерана). Паменшы нейкія або здымі адну з музычнай паловы.",
