"what a probe gave instead of its instrument": "што проба дала замест свайго інструмента",
"Nothing matches.": "Нічога не падыходзіць.",
"⚠ A name in the style is a request, not a promise. What ▶ A and ▶ B play is what YuE2 gives for it, about nine times in ten.": "⚠ Імя ў стылі — просьба, а не абяцанне. Тое, што граюць ▶ A і ▶ B, YuE2 дае на яго прыкладна дзевяць разоў з дзесяці.",
"Some probes are superb, and A and B agree, yet the instrument is not the one asked for: trust the ear, not the name.": "Некаторыя пробы цудоўныя, A і B згодныя, а інструмент не той, пра які прасілі: вер вуху, а не імені.",
"What YuE2 was asked to play, one instrument or one style at a time, in probes of two minutes (one minute for the first ones), two seeds each, A and B.": "Што YuE2 прасілі сыграць — па адным інструменце ці стылі, пробамі па дзве хвіліны (першыя — па хвіліне), з двума сідамі кожная, A і B.",
"An instrument shapes the style of the whole piece: naming one moves the arrangement too. A crackle or a rustle of paper, as on a worn record, is an unlucky seed: make it again on another.": "Інструмент ляпіць стыль усёй рэчы: назваўшы яго, зрушваеш і аранжыроўку. Трэск ці шолах паперы, як на заезджанай пласцінцы, — няўдалы сід: ствары нанава на іншым.",
