"How each step is taken. Euler: the plain step; Euler SDE: fresh noise each step (soft on Qwen without Lightning). ER-SDE: a stochastic solver of third order, one look a step. RES 2s and 3s: the refined exponential solver, two or three looks a step (ODE: without noise). Heun++: up to three looks a step. Exp Heun 2 x0: the exponential Heun, two looks (SDE: with noise). More looks: finer, and as many times longer": "Як выконваецца кожны крок. Euler: просты крок; Euler SDE: свежы шум на кожным кроку (мякка на Qwen без Lightning). ER-SDE: стахастычны развязальнік трэцяга парадку, адзін погляд на крок. RES 2s і 3s: удакладнены экспаненцыяльны развязальнік, два ці тры погляды на крок (ODE: без шуму). Heun++: да трох поглядаў на крок. Exp Heun 2 x0: экспаненцыяльны Heun, два погляды (SDE: з шумам). Больш поглядаў — танчэй і ва столькі ж разоў даўжэй",
"How the steps are spread from the noise to the picture: Simple (the painter's own), Karras and Exponential (more steps near the end, for detail; with Lightning they can paint the subject twice), Beta and Beta 57 (more at both ends), KL optimal (Align Your Steps' spacing), SGM uniform (even in time), Bong tangent (two slopes, through the middle)": "Як крокі размеркаваныя ад шуму да малюнка: Simple (роднае ў мастака), Karras і Exponential (больш крокаў бліжэй да канца, дзеля дэталяў; з Lightning могуць намаляваць сюжэт двойчы), Beta і Beta 57 (больш на абодвух канцах), KL optimal (расстаноўка Align Your Steps), SGM uniform (роўна па часе), Bong tangent (два схілы, праз сярэдзіну)",
