"From the bar at {0} (where the player stands), how many bars: 1, 2, 4 or 8? Seamless, its end running into its start; saved as a WAV.": "З такту на {0} (дзе стаіць плэер) — колькі тактаў: 1, 2, 4 ці 8? Бясшвова, канец пераходзіць у пачатак; захоўваецца як WAV.",
