"A deck's shuffle: every take to a new place": "Тасаванне калоды: кожны сэмпл на новае месца",
"Drag a take to its place; × takes it out of the playlist, never out of the library": "Перацягні сэмпл на яго месца; × прыбірае яго з плэйліста, але не з бібліятэкі",
"Out of the playlist (the take stays)": "Прыбраць з плэйліста (сэмпл застаецца)",
"The playlist is empty: «Add to playlist» in a take's menu puts takes here": "Плэйліст пусты: «Дадаць у плэйліст» у меню сэмпла кладзе сэмплы сюды",
