"no meter (M:)": "няма памеру (M:)",
"the meter is not a meter (M:{0})": "памер — не памер (M:{0})",
"no note length (L:)": "няма даўжыні ноты (L:)",
"the note length is not one (L:{0})": "даўжыня ноты — не даўжыня (L:{0})",
"the tempo is not a tempo (Q:{0})": "тэмп — не тэмп (Q:{0})",
"colons in a run of {0}": "двукроп'і запар: {0}",
"the lowest sound and music loss on the held-out tracks (flow {0}, ar_ce {1})": "найменшыя страты гуку і музыкі на адкладзеных трэках (flow {0}, ar_ce {1})",
"the lowest sound and music loss on the held-out tracks (flow {0})": "найменшыя страты гуку і музыкі на адкладзеных трэках (flow {0})",
"the lowest sound loss on the held-out tracks (flow {0}, ar_ce {1})": "найменшыя страты гуку на адкладзеных трэках (flow {0}, ar_ce {1})",
"the lowest sound loss on the held-out tracks (flow {0})": "найменшыя страты гуку на адкладзеных трэках (flow {0})",
"the lowest music loss on the held-out tracks (flow {0}, ar_ce {1})": "найменшыя страты музыкі на адкладзеных трэках (flow {0}, ar_ce {1})",
// HERESY 1795: the DAW and the piano roll, a beta
"beta": "бэта",
"Beta: we make our songs here every day, and it is all still growing; what it keeps and how it looks may change in a later release.": "Бэта: тут мы штодня творым свае песні, і ўсё гэта яшчэ расце; што захоўваецца і як выглядае, можа змяніцца ў наступных выпусках.",
// HERESY 1794: Ruach Studio's own fine-tune (RS-FW) in the Models card
"RS-FW merge": "Зліццё RS-FW",
"YuE2-3B with Ruach Studio's own fine-tune folded in (YuE2-RS-FW, at seven points of its training: epoch x strength): 2.4x0.75 is the studio's default, the safest; from goldhub/YuE2-RS-Finetunes (CC BY-NC-SA 4.0). Compute chooses it beside m-a-p's backbones; the adapters themselves are not published": "YuE2-3B з уплаўленым уласным файнцюнам Ruach Studio (YuE2-RS-FW, у сямі кропках яго навучання: эпоха x сіла): 2.4x0.75 — мадэль студыі па змаўчанні, самая надзейная; з goldhub/YuE2-RS-Finetunes (CC BY-NC-SA 4.0). «Вылічэнні» выбіраюць яго побач з асноўнымі мадэлямі m-a-p; самі адаптары не публікуюцца",
"The studio's default": "Мадэль студыі па змаўчанні",
"the RS-FW merge {0}": "зліццё RS-FW {0}",
"Ruach Studio's own fine-tune": "уласны файнцюн Ruach Studio",
"Ruach Studio's own fine-tune: RS-FW 2.4x0.75, the studio's default": "Уласны файнцюн Ruach Studio: RS-FW 2.4x0.75, мадэль студыі па змаўчанні",
