// HERESY 1804
"Defaults": "Тыповыя",
"Player": "Плэер",
"⏪ ⏩ step": "Крок ⏪ ⏩",
"Step": "Крок",
"The Studio's Own Writer": "Уласны Пісьменнік Студыі",
"Use this writer": "Пісаць з ім",
"Unload": "Выгрузіць",
"The Writer and its helpers ask this model, at the studio's own address": "Пісьменнік і яго памочнікі пытаюцца ў гэтай мадэлі па ўласным адрасе студыі",
"Free its card now; the next question starts it again": "Вызваліць яго відэакарту зараз; наступнае пытанне зноў яго запусціць",
"Quant": "Квант",
"Which quant the studio's writer runs: quality keeps the AutoRound 4 bits as they are (about 7.5 GB of VRAM), compact keeps those and lowers the rest (about 6.5 GB). Only those here can be chosen": "Які квант запускае ўласны Пісьменнік: якасць — 4 біты AutoRound як ёсць (каля 7,5 ГБ відэапамяці), кампактны — тыя ж 4 біты, астатняе ніжэй (каля 6,5 ГБ). Выбраць можна толькі тыя, што тут",
"Quality: the AutoRound 4 bits as they are (a 12 GB card)": "Якасць: 4 біты AutoRound як ёсць (карта на 12 ГБ)",
"Compact: for an 8 GB card": "Кампактны: для карты на 8 ГБ",
"Not here yet: Engine → Models and LoRAs → Studio writer fetches it (6.7 GB; compact 5.5 GB).": "Пакуль яго тут няма: Рухавік → Мадэлі і LoRA → Пісьменнік Студыі спампуе яго (6,7 ГБ; кампактны 5,5 ГБ).",
"Its weights are here; llama.cpp's llama-server is not built yet: launcher/extras.sh builds it.": "Яго вагі тут; llama-server з llama.cpp яшчэ не сабраны: яго збярэ launcher/extras.sh.",
"Qwopus3.5-9B-v3 (Jackrong's, on Qwen3.5-9B, Apache-2.0), quantized with AutoRound, through llama.cpp on this machine: nothing leaves it. It starts at the first question and leaves the card after 10 minutes without one.": "Qwopus3.5-9B-v3 (ад Jackrong, на аснове Qwen3.5-9B, Apache-2.0), квантаваная AutoRound, праз llama.cpp на гэтай машыне: нічога не сыходзіць вонкі. Запускаецца на першае пытанне і вызваляе карту праз 10 хвілін без пытанняў.",
