"← → keys": "Клавішы ← →",
"Shift + ← →": "Shift + ← →",
"Start playing": "Пачынаць іграць",
"when its first minute is in and the rest will come in time": "калі прыйшла першая хвіліна і астатняе паспее прыйсці",
"when the whole take is in": "калі прыйшоў увесь дубль",
"On a slow line (a studio far away), a take can start before all of it has come: once its first minute is in and the rest will come before the playing reaches it; where it changes to the whole, it does so at a quiet moment. At home the whole comes within seconds, and it waits for it either way.": "На павольнай лініі (студыя далёка) дубль можа пачаць іграць да таго, як прыйдзе ўвесь: як толькі прыйшла яго першая хвіліна і астатняе прыйдзе раней, чым да яго дойдзе гульня; там, дзе ён змяняецца цэлым, гэта адбываецца ў ціхім месцы. Дома цэлае прыходзіць за секунды, і ён у любым выпадку чакае яго.",
"A click on a take plays it": "Клік па дублі яго грае",
"New takes play when they are done": "Новыя дублі граюць, калі гатовыя",
"A double-click on a card plays or stops it": "Двайны клік па картцы — іграць або стоп",
"Show disliked takes in the lists": "Паказваць дызлайкнутыя дублі ў спісах",
"Each is the studio's own until you change it here; the player's and the lists' own switches set the same.": "Кожнае — студыйнае, пакуль ты не зменіш яго тут; уласныя пераключальнікі плэера і спісаў задаюць тое ж самае.",
